        for i in np.random.permutation(len(new_solution))[:3]:
            if new_solution[i] == 1 and current_weight - weight_lst[i] <= capacity:
                new_solution[i] = 0
                current_weight -= weight_lst[i]
            elif new_solution[i] == 0 and current_weight + weight_lst[i] <= capacity:
                new_solution[i] = 1
                current_weight += weight_lst[i]

    # Final feasibility check (optimized)
    total_weight = np.sum(weight_lst * new_solution)
    if total_weight > capacity:
        excess = total_weight - capacity
        excess_items = np.where(new_solution == 1)[0]
        if len(excess_items) > 0:
